              </div>
            ))}
          </div>
        </div>

        <div className="mt-6 text-xs text-[#9a9a9a]">
          数据来源：{API_BASE}/api/potential · 更新于 {new Date(nodes[0]?.updatedAt || Date.now()).toLocaleString('zh-CN')}
        </div>
      </div>
    </div>
  );
}

