        return r.json();
      })
      .then(data => {
        setNodes(data.nodes || []);
        setLoading(false);
      })
      .catch(err => {
        clearTimeout(timer);
        if (err.name === 'AbortError') {
          setError('API 请求超时（8秒），后端响应太慢。请刷新重试。');
        } else {
