            </div>
          </div>
          <div className="mt-6 h-px bg-[#d4d0c8]" />
        </div>

        {/* 心电图 */}
        {allHistory.length > 0 && (
          <div className="mb-6">
            <div className="text-sm text-[#6b6b6b] mb-2">
              {activePhase !== null ? `${PHASE_NAMES[activePhase]} 势位曲线` : '全六相势位曲线'}
