      <div className="max-w-5xl mx-auto">
        <h1 className="text-4xl font-bold mb-2 text-[#1a1a1a]">境</h1>
        <p className="text-[#6b6b6b] mb-6">势位如川，共识如流。六相呼吸，动态呈现。</p>
        <div className="text-[#9a9a9a]">无节点数据</div>
      </div>
    </div>
  );

