                    </div>
                    <div>
                      <div className="text-xs text-[#9a9a9a]">相位</div>
                      <div className="font-bold">{PHASE_NAMES[node.phase ?? 0]}</div>
                    </div>
                    <div>
                      <div className="text-xs text-[#9a9a9a]">势位</div>
                      <div className="font-bold">{node.shiPosition ?? node.phase ?? 0}</div>
