              ))}
            </div>
          </div>
        )}

        {/* 边列表 */}
        {edges.length > 0 && (
          <div className="mb-6">
            <div className="text-sm text-[#6b6b6b] mb-2">边 — 伦理承诺的技术肉身</div>
